`timescale 1ns/1ps

// The grading testbench for milestone 2. Two bits of counter, so the
// saturation is reached inside a short stream.
module tb;

  localparam int W = 2;

  logic clk = 1'b0;
  always #5 clk = ~clk;

  logic rst_n = 1'b1;
  logic din   = 1'b0;
  logic found;
  logic [W-1:0] count;
  logic sat;

  logic [3:0] pattern = 4'b1011;

  seq_detect #(.W(W)) dut (
    .clk(clk), .rst_n(rst_n), .din(din), .pattern(pattern),
    .found(found), .count(count), .sat(sat)
  );

  integer i;

  task tick(input logic b);
    begin
      @(negedge clk); din = b;
      @(posedge clk); #1;
    end
  endtask

  task reset;
    begin
      @(negedge clk); rst_n = 1'b0; din = 1'b0;
      @(posedge clk); #1;
      rst_n = 1'b1;
    end
  endtask

  task stream(input integer n, input [31:0] bits);
    begin
      for (i = n - 1; i >= 0; i = i - 1) tick(bits[i]);
    end
  endtask

  logic [W-1:0] c0, c_long, c_alt, c_sat, c_after_sat, c_reset;
  logic s_before, s_at, s_after, f_wide;

  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb);

    reset();
    c0 = count;

    // Four matches into a counter that stops at three.
    reset();
    stream(18, 18'b101101101110101100);
    tick(1'b0);
    c_long = count;
    s_after = sat;

    reset();
    stream(10, 10'b1010101010);
    tick(1'b0);
    c_alt = count;

    // Exactly three.
    reset();
    stream(10, 10'b1011011011);
    tick(1'b0);
    c_sat = count;
    s_at = sat;

    // One more changes nothing.
    stream(4, 4'b1011);
    tick(1'b0);
    c_after_sat = count;

    // Two: below the limit.
    reset();
    stream(7, 7'b1011011);
    tick(1'b0);
    s_before = sat;

    // The pulse is still one cycle wide through the top.
    reset();
    stream(4, 4'b1011);
    tick(1'b0);
    f_wide = found;

    reset();
    c_reset = count;

    $display("CHECK count_zero_after_reset 0 %0d AT %0d", c0, $time);
    $display("CHECK saturates_not_wraps 3 %0d AT %0d", c_long, $time);
    $display("CHECK sat_high_when_full 1 %0d AT %0d", s_after, $time);
    $display("CHECK alternating_counts_zero 0 %0d AT %0d", c_alt, $time);
    $display("CHECK three_matches_counted 3 %0d AT %0d", c_sat, $time);
    $display("CHECK sat_at_the_limit 1 %0d AT %0d", s_at, $time);
    $display("CHECK stuck_at_the_limit 3 %0d AT %0d", c_after_sat, $time);
    $display("CHECK sat_low_below_limit 0 %0d AT %0d", s_before, $time);
    $display("CHECK found_still_one_cycle 0 %0d AT %0d", f_wide, $time);
    $display("CHECK reset_clears_count 0 %0d AT %0d", c_reset, $time);
    $display("DONE 10");
    $finish;
  end

endmodule

